import { describe, it, expect } from 'vitest';
import { readFileSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ORIGIN, DESTINATIONS, MAP_DESTINATIONS, PLANE_PATH, projectPoint, arcPath, waveOrder }
  from './worldMapData.js';

const here = dirname(fileURLToPath(import.meta.url));
const MAP_PATH = join(here, '..', '..', '..', 'public', 'map', 'world.json');
const world = JSON.parse(readFileSync(MAP_PATH, 'utf8'));

/*
 * world.json is generated by scripts/build-world-map.mjs and committed, so the
 * build stays offline. These tests are what stops a re-run of that script from
 * quietly changing the map: they pin the size, the country count, and the fact
 * that every destination NV sells still has geometry to light up.
 */
describe('world map data', () => {
  it('ships every country outline within the page budget', () => {
    expect(world.countries).toHaveLength(176);
    // 90KB raw, which is ~29KB over the wire once gzipped. It lives in public/,
    // so this is a separate deferred request, not weight on the JS bundle — but
    // an accidental precision bump could double it without anyone noticing.
    expect(statSync(MAP_PATH).size).toBeLessThanOrEqual(90 * 1024);
  });

  it('carries the projection bounds the geometry was built with', () => {
    expect(world.w).toBe(2000);
    expect(world.lonMin).toBe(-180);
    expect(world.lonMax).toBe(180);
    // Antarctica is deliberately cropped; if it came back the south bound would
    // drop past -60 and the whole map would squash.
    expect(world.latMin).toBeGreaterThan(-60);
    expect(world.countries.some((c) => c.name === 'Antarctica')).toBe(false);
  });

  it('never draws a segment across the antimeridian seam', () => {
    // Russia and Fiji have land either side of 180° and the source stores each
    // as one ring stepping straight from lon +179 to lon -179. Projected, that
    // is a full-width horizontal line — it rendered as two orange stripes over
    // the whole map before the generator learned to cut rings at the seam.
    for (const c of world.countries) {
      for (const ring of ringsOf(c.d)) {
        for (let i = 1; i < ring.length; i += 1) {
          expect(
            Math.abs(ring[i][0] - ring[i - 1][0]),
            `${c.name} jumps across the seam`
          ).toBeLessThan(world.w / 2);
        }
      }
    }
  });

  it('gives every country a non-empty closed path and a wave position', () => {
    for (const c of world.countries) {
      expect(c.d.startsWith('M'), `${c.name} path`).toBe(true);
      expect(c.d.endsWith('Z'), `${c.name} path`).toBe(true);
      expect(Number.isFinite(c.cx), `${c.name} cx`).toBe(true);
    }
  });
});

describe('destinations', () => {
  it('resolves every destination to real geometry, or says why not', () => {
    const byId = new Map(world.countries.map((c) => [c.id, c]));
    for (const d of MAP_DESTINATIONS) {
      if (d.pinOnly) {
        // Malta, Singapore and Mauritius are below the dataset's resolution.
        // Asserting they are STILL missing is the point: if a data bump gains
        // them, this fails and someone gets to drop the pinOnly flag.
        expect(byId.has(d.id), `${d.name} unexpectedly gained geometry`).toBe(false);
      } else {
        expect(byId.has(d.id), `${d.name} (id ${d.id}) has no outline`).toBe(true);
      }
    }
  });

  it('excludes "Europe" from the map but keeps it in the list', () => {
    expect(DESTINATIONS.some((d) => d.iso === 'EU')).toBe(true);
    expect(MAP_DESTINATIONS.some((d) => d.iso === 'EU')).toBe(false);
  });

  it('puts every pin inside its own country outline', () => {
    // The failure this catches is a transposed or mistyped lat/lon, which looks
    // perfectly plausible in the source and lands the pin in the sea. Nothing
    // else in the suite would notice.
    const byId = new Map(world.countries.map((c) => [c.id, c]));
    for (const d of MAP_DESTINATIONS) {
      if (d.pinOnly) continue;
      const p = projectPoint(d.lon, d.lat, world);
      const hit = ringsOf(byId.get(d.id).d).some((ring) => contains(ring, p));
      expect(hit, `${d.name}'s pin falls outside ${d.name}`).toBe(true);
    }
  });
});

describe('the plane glyph', () => {
  it('points nose-forward along +x and is centred on the origin', () => {
    // offset-rotate: auto turns the glyph to the route's tangent, so "forward"
    // has to be +x — draw it nose-up and every plane on the map flies sideways.
    // offset-path also positions by the element's centre, so a glyph drawn from
    // (0,0) outward would track a line parallel to its route instead of on it.
    const pts = PLANE_PATH.replace(/^M/, '').replace(/Z$/, '').split('L')
      .map((p) => p.trim().split(' ').map(Number));
    const xs = pts.map((p) => p[0]);
    const ys = pts.map((p) => p[1]);
    const nose = Math.max(...xs);
    const tail = Math.min(...xs);
    expect(nose).toBeGreaterThan(0);
    expect(tail).toBeLessThan(0);
    // Longer than it is wide, and roughly centred on both axes.
    expect(nose - tail).toBeGreaterThan(Math.max(...ys) - Math.min(...ys));
    expect(Math.abs(nose + tail)).toBeLessThan(2);
    expect(Math.abs(Math.max(...ys) + Math.min(...ys))).toBeLessThan(2);
  });
});

describe('projection and arcs', () => {
  it('agrees with the coordinate space the geometry was projected into', () => {
    expect(projectPoint(0, 0, world).x).toBeCloseTo(world.w / 2, 6);
    const topLeft = projectPoint(world.lonMin, world.latMax, world);
    expect(topLeft.x).toBeCloseTo(0, 6);
    expect(topLeft.y).toBeCloseTo(0, 6);
    // One shared scale for both axes — a different vertical scale would stretch
    // the continents out of shape.
    const a = projectPoint(0, 0, world);
    const b = projectPoint(1, -1, world);
    expect(b.x - a.x).toBeCloseTo(b.y - a.y, 9);
  });

  it('draws an arc that starts and ends exactly on its endpoints', () => {
    const from = projectPoint(ORIGIN.lon, ORIGIN.lat, world);
    const to = projectPoint(-0.13, 51.51, world);
    const d = arcPath(from, to);
    const [, sx, sy, , , ex, ey] = d.match(
      /^M([-\d.]+) ([-\d.]+)Q([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+)$/
    );
    expect(Number(sx)).toBeCloseTo(from.x, 1);
    expect(Number(sy)).toBeCloseTo(from.y, 1);
    expect(Number(ex)).toBeCloseTo(to.x, 1);
    expect(Number(ey)).toBeCloseTo(to.y, 1);
  });

  it('orders the draw-on wave west to east across the full 0..1 range', () => {
    const order = waveOrder(world.countries);
    expect(order.size).toBe(world.countries.length);
    const west = [...world.countries].sort((a, b) => a.cx - b.cx)[0];
    const east = [...world.countries].sort((a, b) => b.cx - a.cx)[0];
    expect(order.get(west.id)).toBe(0);
    expect(order.get(east.id)).toBe(1);
  });
});

// Minimal parser for the "M x y L x y … Z" subset the generator emits — it is
// the only path syntax in the file, so this does not need to be a general one.
function ringsOf(d) {
  return d.split('M').filter(Boolean).map((sub) =>
    sub.replace(/Z$/, '').split('L').map((pt) => pt.trim().split(' ').map(Number))
  );
}

function contains(ring, { x, y }) {
  let hit = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i, i += 1) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) hit = !hit;
  }
  return hit;
}
